"""Totals of a bank's CSV export of expenses (date,category,amount)."""
import csv


def load(path):
    with open(path, newline="") as f:
        reader = csv.reader(f)
        next(reader, None)
        return [(date, category, float(amount.replace(",", ""))) for date, category, amount in reader]


def totals(rows):
    out = {}
    for _, category, amount in rows:
        out[category] = round(out.get(category, 0) + amount, 2)
    return out
